// Safeguard marker: INSTAOPS_V2_EXTRACT — extracts media/captions to Supabase Primary + Cloudinary, stops at DRAFT.
const item = $input.first().json || {};
const headers = item.headers || {};
const body = item.body || item;
const expected = String($env.N8N_WEBHOOK_SECRET || '');
const provided = String(headers['x-dashboard-secret'] || headers['X-Dashboard-Secret'] || '');

function safeEqual(a, b) {
  if (!a || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const postUuid = String(body.post_uuid || '').trim();
const postId = String(body.post_id || '').trim();
const sourceUrl = String(body.source_instagram_url || '').trim();
const authorized = body.authorized === true;

let error = '';
if (!expected || !safeEqual(provided, expected)) {
  error = 'Unauthorized webhook secret.';
} else if (!postId || !/^https:\/\/(www\.)?instagram\.com\/(p|reel|reels|tv)\/[A-Za-z0-9_-]+/i.test(sourceUrl)) {
  error = 'Valid post_id and canonical Instagram URL required.';
} else if (!authorized) {
  error = 'Explicit owner authorization (authorized: true) is required.';
}

return [{
  json: {
    valid: !error,
    error,
    httpStatus: error.includes('Unauthorized') ? 403 : error ? 422 : 202,
    post_uuid: postUuid,
    post_id: postId,
    source_instagram_url: sourceUrl,
    expected_revision: String(body.expected_revision || '1'),
    request_id: String(body.request_id || ''),
    job_id: String(body.job_id || ''),
    execution_id: String($execution.id || ''),
    started_at: new Date().toISOString()
  }
}];

const ctx = $('CODE | Validate & Safeguard').item.json;
const sbRaw = $('SUPABASE | Mark Post EXTRACTING').first()?.json;
const sbPost = Array.isArray(sbRaw) ? (sbRaw[0] || {}) : (sbRaw || {});
const postUuid = ctx.post_uuid || sbPost.id || '';
const res = $input.first().json || {};
const hasErr = Boolean(res.error) || res.ok === false || !Array.isArray(res.media) || res.media.length === 0;

if (hasErr) {
  const msg = String(res.message || res.error?.message || res.error || 'Downloader returned empty media array.');
  const isRate = /429|rate|limit|cooldown/i.test(msg);
  return [{
    json: {
      uploadOk: false,
      error_code: isRate ? 'UPSTREAM_RATE_LIMIT' : 'DOWNLOADER_FAILED',
      error_message: msg.slice(0, 500),
      post_uuid: postUuid,
      post_id: ctx.post_id,
      execution_id: ctx.execution_id,
      request_id: ctx.request_id
    }
  }];
}

function sha1Hex(str) {
  function rotl(n, s) { return (n << s) | (n >>> (32 - s)); }
  const utf8 = unescape(encodeURIComponent(str));
  const words = [];
  for (let i = 0; i < utf8.length; i++) words[i >> 2] = (words[i >> 2] || 0) | ((utf8.charCodeAt(i) & 0xff) << (24 - (i % 4) * 8));
  words[utf8.length >> 2] = (words[utf8.length >> 2] || 0) | (0x80 << (24 - (utf8.length % 4) * 8));
  words[((utf8.length + 8) >> 6 << 4) + 15] = utf8.length * 8;
  let h0 = 0x67452301, h1 = 0xefcdab89, h2 = 0x98badcfe, h3 = 0x10325476, h4 = 0xc3d2e1f0;
  const w = new Array(80);
  for (let i = 0; i < words.length; i += 16) {
    let a = h0, b = h1, c = h2, d = h3, e = h4;
    for (let t = 0; t < 80; t++) {
      w[t] = t < 16 ? (words[i + t] || 0) : rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
      const f = t < 20 ? ((b & c) | ((~b) & d)) + 0x5a827999 : t < 40 ? (b ^ c ^ d) + 0x6ed9eba1 : t < 60 ? ((b & c) | (b & d) | (c & d)) + 0x8f1bbcdc : (b ^ c ^ d) + 0xca62c1d6;
      const temp = (rotl(a, 5) + f + e + w[t]) >>> 0;
      e = d; d = c; c = rotl(b, 30) >>> 0; b = a; a = temp;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0; h4 = (h4 + e) >>> 0;
  }
  return [h0, h1, h2, h3, h4].map(n => n.toString(16).padStart(8, '0')).join('');
}

const cloudName = String($env.CLOUDINARY_CLOUD_NAME || 'djkkknb9k');
const apiKey = String($env.CLOUDINARY_API_KEY || '');
const apiSecret = String($env.CLOUDINARY_API_SECRET || '');
const ts = Math.floor(Date.now() / 1000);
const media = res.media;
const mediaCount = media.length;
const imageCount = media.filter(m => String(m.type).toLowerCase() === 'image').length;
const videoCount = media.filter(m => String(m.type).toLowerCase() !== 'image').length;
const mediaType = mediaCount > 1 ? 'CAROUSEL' : videoCount > 0 ? 'REEL' : 'IMAGE';
const meta = res.postMetadata || {};
const sourceId = String(res.sourceId || ctx.post_id).replace(/[^A-Za-z0-9_-]/g, '_');
const safePost = ctx.post_id.replace(/[^A-Za-z0-9_-]/g, '_');

return media.map((m, idx) => {
  const rtype = String(m.type).toLowerCase() === 'image' ? 'image' : 'video';
  const folder = `instaops-v2/${safePost}`;
  const publicId = `item_${idx}_${sourceId}`;
  const toSign = `folder=${folder}&public_id=${publicId}&timestamp=${ts}${apiSecret}`;
  return {
    json: {
      uploadOk: true,
      post_uuid: postUuid,
      post_id: ctx.post_id,
      execution_id: ctx.execution_id,
      request_id: ctx.request_id,
      media_index: idx,
      media_type: mediaType,
      item_media_type: rtype === 'image' ? 'IMAGE' : 'VIDEO',
      resource_type: rtype,
      source_url: String(m.url || ''),
      source_expires_at: String(m.expiresAt || ''),
      cloud_name: cloudName,
      api_key: apiKey,
      timestamp: String(ts),
      folder,
      public_id: publicId,
      signature: sha1Hex(toSign),
      canonical_url: String(res.canonicalUrl || ctx.source_instagram_url),
      source_id: String(res.sourceId || sourceId),
      source_username: String(res.sourceUsername || ''),
      source_kind: String(res.kind || ''),
      original_caption: String(res.caption || ''),
      caption_status: String(res.captionStatus || (res.caption ? 'available' : 'empty')),
      caption_source: String(res.captionSource || 'structured'),
      hashtags: Array.isArray(res.hashtags) ? res.hashtags : [],
      mentions: Array.isArray(res.mentions) ? res.mentions : [],
      media_count: mediaCount,
      image_count: imageCount,
      video_count: videoCount,
      source_published_at: meta.publishedAt || null,
      source_like_count: meta.likeCount ?? null,
      source_comment_count: meta.commentCount ?? null,
      source_play_count: meta.playCount ?? null,
      source_metadata: meta
    }
  };
});

const prepItems = $('CODE | Parse Downloader & Sign Cloudinary').all();
const uploadItems = $input.all();
const now = new Date().toISOString();
const assets = [];
let firstSecureUrl = '';
let totalBytes = 0;
let uploadError = '';

for (let i = 0; i < uploadItems.length; i++) {
  const up = uploadItems[i].json || {};
  const prep = (prepItems[i] && prepItems[i].json) || prepItems[0].json;
  if (up.error || !up.secure_url || !up.public_id) {
    uploadError = String(up.error?.message || up.error || 'Cloudinary upload missing secure_url or public_id');
    break;
  }
  if (!firstSecureUrl) firstSecureUrl = String(up.secure_url);
  const bytes = Number(up.bytes || 0);
  totalBytes += Number.isFinite(bytes) ? bytes : 0;
  assets.push({
    internal_asset_id: `ast_${prep.post_id}_${prep.media_index}`,
    post_uuid: prep.post_uuid,
    post_id: prep.post_id,
    media_index: prep.media_index,
    media_type: prep.item_media_type,
    source_expires_at: prep.source_expires_at || null,
    cloudinary_public_id: String(up.public_id),
    cloudinary_asset_id: String(up.asset_id || ''),
    secure_url: String(up.secure_url),
    thumbnail_url: String(up.secure_url),
    resource_type: String(up.resource_type || prep.resource_type),
    delivery_type: 'upload',
    format: String(up.format || ''),
    file_size_bytes: bytes,
    width: up.width ?? null,
    height: up.height ?? null,
    duration: up.duration ?? null,
    storage_status: 'ACTIVE'
  });
}

const head = prepItems[0].json;
return [{
  json: {
    success: !uploadError,
    post_uuid: head.post_uuid,
    post_id: head.post_id,
    postPatch: {
      media_url: firstSecureUrl,
      media_type: head.media_type,
      original_caption: head.original_caption,
      caption: head.original_caption,
      status: uploadError ? 'FAILED' : 'DRAFT',
      canonical_url: head.canonical_url,
      source_id: head.source_id,
      source_username: head.source_username,
      source_kind: head.source_kind,
      caption_status: head.caption_status,
      caption_source: head.caption_source,
      hashtags: head.hashtags,
      mentions: head.mentions,
      media_count: head.media_count,
      image_count: head.image_count,
      video_count: head.video_count,
      source_published_at: head.source_published_at,
      source_like_count: head.source_like_count,
      source_comment_count: head.source_comment_count,
      source_play_count: head.source_play_count,
      source_metadata: head.source_metadata,
      file_size_bytes: totalBytes,
      revision: (Number($('CODE | Validate & Safeguard').item.json.expected_revision) || 1) + 1,
      approved_revision: null,
      extracted_at: now,
      uploaded_at: now,
      processed_at: now,
      sheets_sync_status: 'PENDING',
      error: uploadError,
      error_code: uploadError ? 'CLOUDINARY_UPLOAD_FAILED' : '',
      error_stage: uploadError ? 'UPLOADING_MEDIA' : '',
      execution_id: head.execution_id,
      request_id: head.request_id
    },
    assets
  }
}];
